    *c += *d; *b ^= *c; *b = rotl32(*b,12);
    *a += *b; *d ^= *a; *d = rotl32(*d,8);
    *c += *d; *b ^= *c; *b = rotl32(*b,7);
}

static void chacha20_block(const u32 key[8], u32 counter, const u32 nonce[3], u32 out[16]){
    u32 x[16];
    x[0]=0x61707865; x[1]=0x3320646e; x[2]=0x79622d32; x[3]=0x6b206574;
    for(int i=0;i<8;i++) x[4+i]=key[i];
    x[12]=counter;
    x[13]=nonce[0]; x[14]=nonce[1]; x[15]=nonce[2];
    u32 s[16]; memcpy(s,x,64);
    for(int i=0;i<10;i++){
        qr(&x[0],&x[4],&x[8],&x[12]);
        qr(&x[1],&x[5],&x[9],&x[13]);
        qr(&x[2],&x[6],&x[10],&x[14]);
        qr(&x[3],&x[7],&x[11],&x[15]);
        qr(&x[0],&x[5],&x[10],&x[15]);
        qr(&x[1],&x[6],&x[11],&x[12]);
        qr(&x[2],&x[7],&x[8],&x[13]);
        qr(&x[3],&x[4],&x[9],&x[14]);
    }
    for(int i=0;i<16;i++) out[i]=x[i]+s[i];
}

/* ---- Poly1305 ---- */
typedef struct {
    u32 r[5];
    u32 h[5];
    u32 pad[4];
} poly1305_state;

static void poly1305_init(poly1305_state *st, const unsigned char key[32]){
    u32 t0,t1,t2,t3;
    t0 = (u32)key[0] | ((u32)key[1]<<8) | ((u32)key[2]<<16) | ((u32)key[3]<<24);
    t1 = (u32)key[4] | ((u32)key[5]<<8) | ((u32)key[6]<<16) | ((u32)key[7]<<24);
    t2 = (u32)key[8] | ((u32)key[9]<<8) | ((u32)key[10]<<16) | ((u32)key[11]<<24);
    t3 = (u32)key[12] | ((u32)key[13]<<8) | ((u32)key[14]<<16) | ((u32)key[15]<<24);

    st->r[0] = t0 & 0x3ffffff; t0 >>= 26; t0 |= t1 << 6;
    st->r[1] = t0 & 0x3ffff03; t1 >>= 20; t1 |= t2 << 12;
    st->r[2] = t1 & 0x3ffc0ff; t2 >>= 14; t2 |= t3 << 18;
    st->r[3] = t2 & 0x3f03fff; t3 >>= 8;
    st->r[4] = t3 & 0x00fffff;

    st->pad[0] = (u32)key[16] | ((u32)key[17]<<8) | ((u32)key[18]<<16) | ((u32)key[19]<<24);
    st->pad[1] = (u32)key[20] | ((u32)key[21]<<8) | ((u32)key[22]<<16) | ((u32)key[23]<<24);
    st->pad[2] = (u32)key[24] | ((u32)key[25]<<8) | ((u32)key[26]<<16) | ((u32)key[27]<<24);
    st->pad[3] = (u32)key[28] | ((u32)key[29]<<8) | ((u32)key[30]<<16) | ((u32)key[31]<<24);

    st->h[0]=st->h[1]=st->h[2]=st->h[3]=st->h[4]=0;
}

/* process one full 16-byte block (always with hibit) */
static void poly1305_block(poly1305_state *st, const unsigned char *m){
    u32 r0=st->r[0],r1=st->r[1],r2=st->r[2],r3=st->r[3],r4=st->r[4];
    u32 s1=r1*5,s2=r2*5,s3=r3*5,s4=r4*5;
    u32 h0=st->h[0],h1=st->h[1],h2=st->h[2],h3=st->h[3],h4=st->h[4];

    u32 t0 = (u32)m[0] | ((u32)m[1]<<8) | ((u32)m[2]<<16) | ((u32)m[3]<<24);
    u32 t1 = (u32)m[4] | ((u32)m[5]<<8) | ((u32)m[6]<<16) | ((u32)m[7]<<24);
    u32 t2 = (u32)m[8] | ((u32)m[9]<<8) | ((u32)m[10]<<16) | ((u32)m[11]<<24);
    u32 t3 = (u32)m[12] | ((u32)m[13]<<8) | ((u32)m[14]<<16) | ((u32)m[15]<<24);

    h0 += t0 & 0x3ffffff;
    h1 += (((u64)t1 << 32) | t0) >> 26 & 0x3ffffff;
    h2 += (((u64)t2 << 32) | t1) >> 20 & 0x3ffffff;
    h3 += (((u64)t3 << 32) | t2) >> 14 & 0x3ffffff;
    h4 += (t3 >> 8) | (1u<<24);

    u64 d0 = (u64)h0*r0 + (u64)h1*s4 + (u64)h2*s3 + (u64)h3*s2 + (u64)h4*s1;
    u64 d1 = (u64)h0*r1 + (u64)h1*r0 + (u64)h2*s4 + (u64)h3*s3 + (u64)h4*s2;
    u64 d2 = (u64)h0*r2 + (u64)h1*r1 + (u64)h2*r0 + (u64)h3*s4 + (u64)h4*s3;
    u64 d3 = (u64)h0*r3 + (u64)h1*r2 + (u64)h2*r1 + (u64)h3*r0 + (u64)h4*s4;
    u64 d4 = (u64)h0*r4 + (u64)h1*r3 + (u64)h2*r2 + (u64)h3*r1 + (u64)h4*r0;

    u32 c;
    c = (u32)(d0 >> 26); h0 = (u32)d0 & 0x3ffffff;
    d1 += c; c = (u32)(d1 >> 26); h1 = (u32)d1 & 0x3ffffff;
    d2 += c; c = (u32)(d2 >> 26); h2 = (u32)d2 & 0x3ffffff;
    d3 += c; c = (u32)(d3 >> 26); h3 = (u32)d3 & 0x3ffffff;
    d4 += c; c = (u32)(d4 >> 26); h4 = (u32)d4 & 0x3ffffff;
    h0 += c*5; c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    st->h[0]=h0; st->h[1]=h1; st->h[2]=h2; st->h[3]=h3; st->h[4]=h4;
}

/* H = H * R + P  (all 5-limb, partial reduction) */
static void poly1305_muladd(u32 h[5], const u32 R[5], const u32 P[5]){
    u32 r0=R[0],r1=R[1],r2=R[2],r3=R[3],r4=R[4];
    u32 s1=r1*5,s2=r2*5,s3=r3*5,s4=r4*5;
    u32 h0=h[0],h1=h[1],h2=h[2],h3=h[3],h4=h[4];

    u64 d0 = (u64)h0*r0 + (u64)h1*s4 + (u64)h2*s3 + (u64)h3*s2 + (u64)h4*s1 + P[0];
    u64 d1 = (u64)h0*r1 + (u64)h1*r0 + (u64)h2*s4 + (u64)h3*s3 + (u64)h4*s2 + P[1];
    u64 d2 = (u64)h0*r2 + (u64)h1*r1 + (u64)h2*r0 + (u64)h3*s4 + (u64)h4*s3 + P[2];
    u64 d3 = (u64)h0*r3 + (u64)h1*r2 + (u64)h2*r1 + (u64)h3*r0 + (u64)h4*s4 + P[3];
    u64 d4 = (u64)h0*r4 + (u64)h1*r3 + (u64)h2*r2 + (u64)h3*r1 + (u64)h4*r0 + P[4];

    u32 c;
    c = (u32)(d0 >> 26); h0 = (u32)d0 & 0x3ffffff;
    d1 += c; c = (u32)(d1 >> 26); h1 = (u32)d1 & 0x3ffffff;
    d2 += c; c = (u32)(d2 >> 26); h2 = (u32)d2 & 0x3ffffff;
    d3 += c; c = (u32)(d3 >> 26); h3 = (u32)d3 & 0x3ffffff;
    d4 += c; c = (u32)(d4 >> 26); h4 = (u32)d4 & 0x3ffffff;
    h0 += c*5; c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    h[0]=h0; h[1]=h1; h[2]=h2; h[3]=h3; h[4]=h4;
}

/* compute R = r^e mod p (5-limb), r is the clamped key */
static void poly1305_pow(u32 R[5], const u32 r[5], u64 e){
    u32 base[5]; memcpy(base, r, 20);
    u32 res[5] = {1,0,0,0,0};
    while(e){
        if(e & 1){
            poly1305_muladd(res, base, (u32[5]){0,0,0,0,0});
        }
        poly1305_muladd(base, base, (u32[5]){0,0,0,0,0});
        e >>= 1;
    }
    memcpy(R, res, 20);
}

static void poly1305_finish(poly1305_state *st, unsigned char mac[16]){
    u32 h0=st->h[0],h1=st->h[1],h2=st->h[2],h3=st->h[3],h4=st->h[4];
    u32 g0,g1,g2,g3,g4,c;

    c = h1 >> 26; h1 &= 0x3ffffff;
    h2 += c; c = h2 >> 26; h2 &= 0x3ffffff;
    h3 += c; c = h3 >> 26; h3 &= 0x3ffffff;
    h4 += c; c = h4 >> 26; h4 &= 0x3ffffff;
    h0 += c*5; c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    g0 = h0 + 5; c = g0 >> 26; g0 &= 0x3ffffff;
    g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    g4 = h4 + c - (1u<<26);

    u32 mask = (g4 >> 31) - 1;
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    h0 = (h0 | (h1 << 26)) & 0xffffffff;
    h1 = ((h1 >> 6) | (h2 << 20)) & 0xffffffff;
    h2 = ((h2 >> 12) | (h3 << 14)) & 0xffffffff;
    h3 = ((h3 >> 18) | (h4 << 8)) & 0xffffffff;

    u64 f;
    f = (u64)h0 + st->pad[0]; mac[0]=(unsigned char)f; mac[1]=(unsigned char)(f>>8); mac[2]=(unsigned char)(f>>16); mac[3]=(unsigned char)(f>>24);
    f = (u64)h1 + st->pad[1] + (f>>32); mac[4]=(unsigned char)f; mac[5]=(unsigned char)(f>>8); mac[6]=(unsigned char)(f>>16); mac[7]=(unsigned char)(f>>24);
    f = (u64)h2 + st->pad[2] + (f>>32); mac[8]=(unsigned char)f; mac[9]=(unsigned char)(f>>8); mac[10]=(unsigned char)(f>>16); mac[11]=(unsigned char)(f>>24);
    f = (u64)h3 + st->pad[3] + (f>>32); mac[12]=(unsigned char)f; mac[13]=(unsigned char)(f>>8); mac[14]=(unsigned char)(f>>16); mac[15]=(unsigned char)(f>>24);
}

/* ---- multithreaded encrypt ---- */

#define MAX_THREADS 64

typedef struct {
    const u32 *key;
    const u32 *nonce;
    const unsigned char *plaintext;
    unsigned char *ciphertext;
    size_t start;   // byte offset
    size_t end;     // byte offset (exclusive)
    u32 counter_start;
    const u32 *r;   // poly1305 r (5 limbs)
    u32 P[5];       // output partial
} thread_arg;

static void* worker(void *argp){
    thread_arg *a = (thread_arg*)argp;
    const u32 *key = a->key;
    const u32 *nonce = a->nonce;
    const unsigned char *pt = a->plaintext;
    unsigned char *ct = a->ciphertext;
    size_t off = a->start;
    size_t end = a->end;
    u32 counter = a->counter_start;

    poly1305_state st;
    st.r[0]=a->r[0]; st.r[1]=a->r[1]; st.r[2]=a->r[2]; st.r[3]=a->r[3]; st.r[4]=a->r[4];
    st.h[0]=st.h[1]=st.h[2]=st.h[3]=st.h[4]=0;

    while(off < end){
        u32 block[16];
        chacha20_block(key, counter, nonce, block);
        unsigned char ks[64];
        for(int i=0;i<16;i++){
            ks[4*i]   = (unsigned char)block[i];
            ks[4*i+1] = (unsigned char)(block[i]>>8);
            ks[4*i+2] = (unsigned char)(block[i]>>16);
            ks[4*i+3] = (unsigned char)(block[i]>>24);
        }
        size_t nbytes = end - off;
        if(nbytes > 64) nbytes = 64;
        for(size_t i=0;i<nbytes;i++) ct[off+i] = pt[off+i] ^ ks[i];
        // poly1305 over this ciphertext chunk (16-byte blocks)
        size_t b = 0;
        while(b + 16 <= nbytes){
            poly1305_block(&st, ct + off + b);
            b += 16;
        }
        if(b < nbytes){
            unsigned char buf[16];
            memset(buf, 0, 16);
            memcpy(buf, ct + off + b, nbytes - b);
            poly1305_block(&st, buf);
        }
        off += nbytes;
        counter++;
    }
    a->P[0]=st.h[0]; a->P[1]=st.h[1]; a->P[2]=st.h[2]; a->P[3]=st.h[3]; a->P[4]=st.h[4];
    return 0;
}

void chacha20poly1305_encrypt_mt(
    const unsigned char *key, const unsigned char *nonce,
    const unsigned char *aad, size_t aad_len,
    const unsigned char *plaintext, size_t pt_len,
    unsigned char *ciphertext, unsigned char *tag,
    int nthreads)
{
    u32 k[8];
    for(int i=0;i<8;i++) k[i] = (u32)key[4*i] | ((u32)key[4*i+1]<<8) | ((u32)key[4*i+2]<<16) | ((u32)key[4*i+3]<<24);
    u32 n[3];
    n[0] = (u32)nonce[0] | ((u32)nonce[1]<<8) | ((u32)nonce[2]<<16) | ((u32)nonce[3]<<24);
    n[1] = (u32)nonce[4] | ((u32)nonce[5]<<8) | ((u32)nonce[6]<<16) | ((u32)nonce[7]<<24);
    n[2] = (u32)nonce[8] | ((u32)nonce[9]<<8) | ((u32)nonce[10]<<16) | ((u32)nonce[11]<<24);

    u32 block0[16];
    chacha20_block(k, 0, n, block0);
    unsigned char polykey[32];
    for(int i=0;i<8;i++){
        polykey[4*i]   = (unsigned char)block0[i];
        polykey[4*i+1] = (unsigned char)(block0[i]>>8);
        polykey[4*i+2] = (unsigned char)(block0[i]>>16);
        polykey[4*i+3] = (unsigned char)(block0[i]>>24);
    }

    poly1305_state st;
    poly1305_init(&st, polykey);
    u32 r[5]; memcpy(r, st.r, 20);

    // process AAD
    {
        size_t off = 0;
        while(off + 16 <= aad_len){
            poly1305_block(&st, aad + off);
            off += 16;
        }
        if(off < aad_len){
            unsigned char buf[16];
            memset(buf, 0, 16);
            memcpy(buf, aad + off, aad_len - off);
            poly1305_block(&st, buf);
        }
    }

    if(nthreads > MAX_THREADS) nthreads = MAX_THREADS;
    if(nthreads < 1) nthreads = 1;

    // chunk boundaries at 64-byte multiples
    size_t total64 = (pt_len + 63) / 64;
    size_t per = (total64 + nthreads - 1) / nthreads;

    pthread_t threads[MAX_THREADS];
    thread_arg args[MAX_THREADS];
    int nt = 0;
    for(int i=0;i<nthreads;i++){
        size_t s64 = (size_t)i * per;
        if(s64 >= total64) break;
        size_t e64 = s64 + per;
        if(e64 > total64) e64 = total64;
        args[nt].key = k;
        args[nt].nonce = n;
        args[nt].plaintext = plaintext;
        args[nt].ciphertext = ciphertext;
        args[nt].start = s64 * 64;
        args[nt].end = e64 * 64;
        if(args[nt].end > pt_len) args[nt].end = pt_len;
        args[nt].counter_start = 1 + (u32)s64;
        args[nt].r = r;
        nt++;
    }

    for(int i=0;i<nt;i++) pthread_create(&threads[i], 0, worker, &args[i]);
    for(int i=0;i<nt;i++) pthread_join(threads[i], 0);

    // combine partials: H = P_0; for i: H = H * r^{len_i} + P_i
    u32 H[5] = {args[0].P[0], args[0].P[1], args[0].P[2], args[0].P[3], args[0].P[4]};
    for(int i=1;i<nt;i++){
        size_t len_i = (args[i].end - args[i].start) / 16;
        u32 R[5];
        poly1305_pow(R, r, len_i);
        poly1305_muladd(H, R, args[i].P);
    }

    st.h[0]=H[0]; st.h[1]=H[1]; st.h[2]=H[2]; st.h[3]=H[3]; st.h[4]=H[4];

    // length block
    unsigned char lens[16];
    u64 al = (u64)aad_len, pl = (u64)pt_len;
    for(int i=0;i<8;i++){ lens[i] = (unsigned char)(al >> (8*i)); lens[8+i] = (unsigned char)(pl >> (8*i)); }
    poly1305_block(&st, lens);

    poly1305_finish(&st, tag);
}
